    def take(self, indexer, axis=1, verify=True, convert=True):
        """
        Take items along any axis.
        """
        self._consolidate_inplace()
        indexer = np.arange(indexer.start, indexer.stop, indexer.step,
                            dtype='int64') if isinstance(indexer, slice) \
